<script setup lang="ts">definePageMeta({ middleware:'auth' }); const user=useSupabaseUser(); const supabase=useSupabaseClient(); const results=ref<any[]>([]); onMounted(async()=>{const{data}=await supabase.from('results').select('position,result_display,points,event:events(name,event_date,sport:sports(name))').eq('student_id',user.value!.id).order('created_at',{ascending:false});results.value=data||[]})</script>
<template><main class="mx-auto max-w-5xl px-4 py-8"><p class="text-sm font-bold uppercase tracking-wider text-blue-600">Student</p><h1 class="mt-1 text-3xl font-bold">My Results</h1><div class="mt-6 overflow-hidden rounded-xl border bg-white"><table class="w-full text-left"><thead class="bg-slate-50"><tr><th class="p-4">Event</th><th>Date</th><th>Result</th><th>Place</th><th>Points</th></tr></thead><tbody><tr v-for="r in results" :key="`${r.event?.name}-${r.event?.event_date}`" class="border-t"><td class="p-4 font-semibold">{{r.event?.name}}</td><td>{{r.event?.event_date}}</td><td>{{r.result_display}}</td><td>{{r.position||'—'}}</td><td>{{r.points}}</td></tr><tr v-if="!results.length"><td colspan="5" class="p-8 text-center text-slate-500">No results recorded yet.</td></tr></tbody></table></div></main></template>
